--region lifecycle
function ActivityDreamAdventuresNode:__init()
    self._activityDojo = nil
end

function ActivityDreamAdventuresNode:__delete()
    self._activityDojo = nil
end

function ActivityDreamAdventuresNode:Awake()
    self:InitHandler()
end


function ActivityDreamAdventuresNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
