--region handler
---入口点击回调
function ActivityDreamAdventuresNode:EntryOnClickHandler()
    if isNull(self._activityDojo) then
        return
    end
    if not self.isUnlock then
        local vo = self._activityDojo.unlock[1]
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        GameUtils.Toast(err)
        return
    end
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._activityDojo.id)))
    DreamAdvUtils.EnterDreamAdventures({ {id = Constants.UITypeIds.UIActivityMainDialog} }, {activityDojo = self._activityDojo, random = true})
end
--endregion handler

--region public
---刷新自身
---@param activityDojo ActivityDojo
function ActivityDreamAdventuresNode:Refresh(activityDojo)
    self._activityDojo = activityDojo
    if isNull(self._activityDojo) then return end

    local vo = checkTable(self._activityDojo.unlock)[1]
    if vo then
        self.isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
    else
        self.isUnlock = true
    end
    
    self:RefreshUI()
end
--endregion public

--region private
---刷新UI
---@param activityDojo ActivityDojo
function ActivityDreamAdventuresNode:RefreshUI()
    self:RefreshActivityTime()
    self:RefreshStateGroup()
    self:RefreshEndTime()
end

---刷新活动时间
function ActivityDreamAdventuresNode:RefreshActivityTime()
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self._activityDojo.startTime, self._activityDojo.endTime))
end

---刷新活动详情
function ActivityDreamAdventuresNode:RefreshStateGroup()
    CfUtils.FillText(self.Text, self._activityDojo.detail)
end

---刷新结束时间
function ActivityDreamAdventuresNode:RefreshEndTime()
    CfUtils.FillText(self.TextTime2, ActivityUtils.ConvertActivityCloseTime(self._activityDojo.closeTime))

    if not self.isUnlock then
        local vo = self._activityDojo.unlock[1]
        local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
        CfUtils.FillText(self.TextLockDesc, err)
    end
    CfUtils.SetActive(self.ImgBg, self.isUnlock)
    CfUtils.SetActive(self.ImgLockBg, not self.isUnlock)
end
--endregion private

return ActivityDreamAdventuresNode